def _SUBIN_DYNAMIC_WEED_BASE(obs, config=None):
    action = copy.deepcopy(_SUBIN_SOMEWHERE_ROUTER_BASE(obs, config))
    step = min(int(obs.get("step", 0) or 0), len(_SOMEWHERE_ROUTER_MARKET) - 1)
    if step >= 704:
        return action
    shops = tuple((obs.get("town", {}) or {}).get("unlocked_shops", []) or [])
    if shops[:3] not in _SOMEWHERE_ROUTER_BASE_PREFIXES:
        action["market"] = copy.deepcopy(_SOMEWHERE_ROUTER_MARKET[step])
    return action



_DYNAMIC_WEED_ACTIVE = {}


def _dynamic_weed_tile(farm, position):
    try:
        x, y = int(position[0]), int(position[1])
        return (farm.get("tiles", []) or [])[y][x]
    except (IndexError, TypeError, ValueError):
        return "LOCKED"


def _dynamic_trace_action(step, actor):
    trace = TRACE_ACTIONS[min(max(step, 0), len(TRACE_ACTIONS) - 1)]
    if actor == "farmer":
        return copy.deepcopy(trace.get("farmer", ["PASS"]) or ["PASS"])
    hands = trace.get("hands", []) or []
    return copy.deepcopy(hands[actor] if actor < len(hands) else ["PASS"])


def _SUBIN_DYNAMIC_WEED_MARKET_LATCH_BASE(obs, config=None):
    global _DYNAMIC_WEED_ACTIVE
    action = copy.deepcopy(_SUBIN_DYNAMIC_WEED_BASE(obs, config))
    step = int(obs.get("step", 0) or 0)
    if step == 0:
        _DYNAMIC_WEED_ACTIVE = {}
    player = int(obs.get("player", 0) or 0)
    farms = obs.get("farms", []) or []
    if player not in (0, 1) or len(farms) != 2:
        return action
    farm = farms[player] or {}
    hand_positions = list(farm.get("hands", []) or [])
    hand_actions = list(action.get("hands", []) or [])

    for actor, start in list(_DYNAMIC_WEED_ACTIVE.items()):
        if actor != "farmer" and actor >= min(len(hand_positions), len(hand_actions)):
            _DYNAMIC_WEED_ACTIVE.pop(actor, None)
            continue
        current = action.get("farmer", ["PASS"]) if actor == "farmer" else hand_actions[actor]
        if step == start + 1:
            replacement = ["BUILD_PASTURE"]
        else:
            previous = _dynamic_trace_action(step - 1, actor)
            if current == previous:
                _DYNAMIC_WEED_ACTIVE.pop(actor, None)
                continue
            replacement = previous
        if actor == "farmer":
            action["farmer"] = replacement
        else:
            hand_actions[actor] = replacement

    farmer_position = farm.get("farmer")
    if "farmer" not in _DYNAMIC_WEED_ACTIVE:
        tile = _dynamic_weed_tile(farm, farmer_position)
        if (
            action.get("farmer") == ["BUILD_PASTURE"]
            and isinstance(tile, dict) and tile.get("kind") == "WEED"
        ):
            _DYNAMIC_WEED_ACTIVE["farmer"] = step
            action["farmer"] = ["DIG"]

    for index in range(min(len(hand_positions), len(hand_actions))):
        if index in _DYNAMIC_WEED_ACTIVE:
            continue
        tile = _dynamic_weed_tile(farm, hand_positions[index])
        if (
            hand_actions[index] == ["BUILD_PASTURE"]
            and isinstance(tile, dict) and tile.get("kind") == "WEED"
        ):
            _DYNAMIC_WEED_ACTIVE[index] = step
            hand_actions[index] = ["DIG"]
    action["hands"] = hand_actions
    return action

