_DYNAMIC_WEED_MARKET_LATCH_PREFIX = (
    "BRUNCH_SPOT", "FARMERS_MARKET", "PET_CAFE", "YARN_STORE",
)
_DYNAMIC_WEED_MARKET_LATCH_ACTIVE = False


def _SUBIN_PLANT_WEED_FIXED_BASE(obs, config=None):
    global _DYNAMIC_WEED_MARKET_LATCH_ACTIVE
    action = copy.deepcopy(_SUBIN_DYNAMIC_WEED_MARKET_LATCH_BASE(obs, config))
    step = min(
        int(obs.get("step", 0) or 0),
        len(_DYNAMIC_WEED_MARKET_LATCH_TAPE) - 1,
    )
    if step == 0:
        _DYNAMIC_WEED_MARKET_LATCH_ACTIVE = False
    shops = tuple((obs.get("town", {}) or {}).get("unlocked_shops", []) or [])
    if step == 288 and shops[:4] == _DYNAMIC_WEED_MARKET_LATCH_PREFIX:
        prices = ((obs.get("market", {}) or {}).get("prices", {}) or {})
        _DYNAMIC_WEED_MARKET_LATCH_ACTIVE = (
            float(prices.get("MILK", 0) or 0) >= 140
            and float(prices.get("MELON", 0) or 0) <= 220
        )
    if _DYNAMIC_WEED_MARKET_LATCH_ACTIVE and step < 704:
        action["market"] = copy.deepcopy(_DYNAMIC_WEED_MARKET_LATCH_TAPE[step])
    return action



_PLANT_WEED_FIXED_REPLAY_STEPS = 8
_PLANT_WEED_FIXED_SKIP_PREFIXES = (('FARMERS_MARKET', 'BAKERY', 'SMOOTHIE_SHOP'),)
_PLANT_WEED_FIXED_ACTIVE = {}


def _plant_weed_fixed_trace_action(step, actor):
    trace = TRACE_ACTIONS[min(max(step, 0), len(TRACE_ACTIONS) - 1)]
    if actor == "farmer":
        return copy.deepcopy(trace.get("farmer", ["PASS"]) or ["PASS"])
    hands = trace.get("hands", []) or []
    return copy.deepcopy(hands[actor] if actor < len(hands) else ["PASS"])


def _SUBIN_V15_CONSERVATIVE_BASE(obs, config=None):
    global _PLANT_WEED_FIXED_ACTIVE
    action = copy.deepcopy(_SUBIN_PLANT_WEED_FIXED_BASE(obs, config))
    step = int(obs.get("step", 0) or 0)
    if step == 0:
        _PLANT_WEED_FIXED_ACTIVE = {}
    player = int(obs.get("player", 0) or 0)
    farms = obs.get("farms", []) or []
    if player not in (0, 1) or len(farms) != 2:
        return action
    farm = farms[player] or {}
    hand_positions = list(farm.get("hands", []) or [])
    hand_actions = list(action.get("hands", []) or [])
    shops = tuple((obs.get("town", {}) or {}).get("unlocked_shops", []) or [])
    repair_enabled = shops[:3] not in _PLANT_WEED_FIXED_SKIP_PREFIXES

    for actor, state in list(_PLANT_WEED_FIXED_ACTIVE.items()):
        start, intended = state
        if actor != "farmer" and actor >= min(len(hand_positions), len(hand_actions)):
            _PLANT_WEED_FIXED_ACTIVE.pop(actor, None)
            continue
        age = step - start
        if age == 1:
            replacement = copy.deepcopy(intended)
        elif 2 <= age <= 1 + _PLANT_WEED_FIXED_REPLAY_STEPS:
            replacement = _plant_weed_fixed_trace_action(step - 1, actor)
        else:
            _PLANT_WEED_FIXED_ACTIVE.pop(actor, None)
            continue
        if actor == "farmer":
            action["farmer"] = replacement
        else:
            hand_actions[actor] = replacement

    farmer_position = farm.get("farmer")
    if repair_enabled and "farmer" not in _PLANT_WEED_FIXED_ACTIVE:
        tile = _dynamic_weed_tile(farm, farmer_position)
        intended = action.get("farmer", ["PASS"])
        if (
            isinstance(intended, list) and intended[:1] == ["PLANT"]
            and isinstance(tile, dict) and tile.get("kind") == "WEED"
        ):
            _PLANT_WEED_FIXED_ACTIVE["farmer"] = (step, copy.deepcopy(intended))
            action["farmer"] = ["DIG"]

    for index in range(min(len(hand_positions), len(hand_actions))):
        if not repair_enabled:
            break
        if index in _PLANT_WEED_FIXED_ACTIVE:
            continue
        tile = _dynamic_weed_tile(farm, hand_positions[index])
        intended = hand_actions[index]
        if (
            isinstance(intended, list) and intended[:1] == ["PLANT"]
            and isinstance(tile, dict) and tile.get("kind") == "WEED"
        ):
            _PLANT_WEED_FIXED_ACTIVE[index] = (step, copy.deepcopy(intended))
            hand_actions[index] = ["DIG"]
    action["hands"] = hand_actions
    return action



